      {n:'Roasted Hazelnut Moon',img:'moon_hazelnut',d:'Roasted whole hazelnuts in each crescent bite.',price:null,size:'',notes:[['Texture','Small snap'],['Sweetness','Gentle carob'],['Finish','Hazelnut'],['Details','Enquire']]}
