/* PHOTO VARIANT (dev): per-slot photography swap, driven by URL params so the picker playground
   can live-preview real choices. ?s1=ocean|moontrail|duo23 &s3=ai|pod66 &s4=ai|eco55|barstack21
   &s5=ai|duo23|trio43|eco55light  — defaults = recommended picks from the locked 2026-06-13 shortlist. */
(function(){
  var PF='/assets/photo_finals/';
  var q=new URLSearchParams(location.search);
