})();

(function(){
  var reduce=window.matchMedia('(prefers-reduced-motion:reduce)').matches;
  var targets=document.querySelectorAll('section:not(#top), footer:not(.wf-ptop)');
  if(!targets.length)return;
  targets.forEach(function(el){el.setAttribute('data-reveal','');});
  var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('is-visible');io.unobserve(e.target);}});},{threshold:0.12,rootMargin:'0px 0px -40px 0px'});
  var st=document.getElementById('motionState');
  function enable(){document.body.classList.add('motion-on');targets.forEach(function(el){el.classList.remove('is-visible');io.observe(el);});st.textContent=reduce?'reduced':'on';}
  function disable(){document.body.classList.remove('motion-on');targets.forEach(function(el){io.unobserve(el);el.classList.add('is-visible');});st.textContent='off';}
  var on=false;(on?enable:disable)();
  document.getElementById('motionToggle').addEventListener('click',function(){on=!on;(on?enable:disable)();});
})();

