      {n:'Eclipse Bite Bundle',img:'eclipse_bundle',d:'Can\'t decide? Try the range. All 5 bites to satisfy your cravings and curiosity.',price:null,size:''}
    ],
    elixirs:[
      {n:'Pure Carob Elixir',img:'elixir_plain',d:'A warm carob drink with only two ingredients, naturally sweet and caffeine free.',size:'(150g)',sel:true},
      {n:'Spiced Carob Elixir',img:'elixir_spiced',d:'A warm carob drink with an Ayurvedic inspired spice blend',size:'(150g)',notes:[['Texture','Silky drink'],['Sweetness','Naturally sweet'],['Finish','Gentle spice'],['Proof','Caffeine free']]}
    ],
    bananas:[
      {n:'Carob Bananas',img:'bananas_real',d:'Spray Free Australian Grown Bananas coated in our pure carob for the perfect chewy treat.',price:null,size:'',sel:true}
    ]
  };
  var PRICE_STATE={
    bars:{priced:true,label:'Available now'},
    elixirs:{priced:true,label:'Available now'},
    moons:{priced:false,label:'Enquire for details'},
    eclipseBites:{priced:false,label:'Enquire for details'},
    bananas:{priced:false,label:'Enquire for details'}
  };
  var SIZES={
    bars:[],
    elixirs:[{label:'150g jar'}],
    bananas:[{label:'80g'}]
  };

  var stage=document.getElementById('stage');
  var tabs=document.getElementById('catTabs');
  var rangeCopy=document.getElementById('rangeCopy');
  var pdpEyebrow=document.getElementById('pdpEyebrow');
  var pdpName=document.getElementById('pdpName');
  var pdpDesc=document.getElementById('pdpDesc');
  var pdpPrice=document.getElementById('pdpPrice');
  var pdpFlag=document.getElementById('pdpFlag');
  var pdpProof=document.getElementById('pdpProof');
  var pdpNotes=document.getElementById('pdpNotes');
  var pdpSizes=document.getElementById('pdpSizes');
  var pdpAdd=document.getElementById('pdpAdd');
  if(!stage||!tabs)return;
  var catDock=tabs.closest('.wf-cat-dock');
  var catPrev=catDock&&catDock.querySelector('.cat-prev');
  var catNext=catDock&&catDock.querySelector('.cat-next');

  // names come from the trusted in-file catalog above; wrap "&" in the Georgia .amp the brand uses
  function amp(s){return s.replace(/&/g,'<span class="amp">&amp;</span>');}
  var currentCat='bars';
  var CAT_ORDER=['bars','bananas','moons','eclipseBites','elixirs'];
  var CAT_LABEL={bars:'Selected bar',moons:'Selected moon',eclipseBites:'Selected treat',elixirs:'Selected elixir',bananas:'Selected banana'};
  var CAT_FORMAT={bars:'Carob Bars',moons:'Carob Moons',eclipseBites:'Eclipse Bites',elixirs:'Carob Elixirs',bananas:'Carob Bananas'};
  var CAT_SHOP_TARGET={bars:'/shop#bars',moons:'/shop#moons',eclipseBites:'/shop#bites',elixirs:'/shop#elixirs',bananas:'/shop#bananas'};
  var NOTE_FALLBACK={
    bars:[['Texture','Smooth melt'],['Sweetness','Naturally sweet'],['Finish','Buttery carob'],['Proof','No caffeine']],
    moons:[['Texture','Small snap'],['Sweetness','Gentle carob'],['Finish','Clean finish'],['Details','Enquire']],
    eclipseBites:[['Texture','Whole ingredients'],['Sweetness','Naturally sweet'],['Finish','Pure carob'],['Details','Enquire']],
    elixirs:[['Texture','Silky drink'],['Sweetness','Naturally sweet'],['Finish','Mellow roast'],['Proof','Caffeine free']],
    bananas:[['Texture','Chewy fruit'],['Sweetness','Banana sweet'],['Finish','Soft carob'],['Details','Enquire']]
  };
  function shopTarget(cat){return CAT_SHOP_TARGET[cat]||'/shop';}
  function catIndex(cat){var i=CAT_ORDER.indexOf(cat);return i<0?0:i;}
  function updateTabs(activeCat){
    [].slice.call(tabs.querySelectorAll('.wf-tab')).forEach(function(el){
      var cat=el.getAttribute('data-cat');
      el.classList.toggle('on',cat===activeCat);
      el.setAttribute('aria-pressed',cat===activeCat?'true':'false');
      el.setAttribute('aria-selected',cat===activeCat?'true':'false');
    });
  }
  function activePack(){
    var sz=pdpSizes&&pdpSizes.querySelector('.wf-sz.on[data-price]');
    return sz?{price:sz.getAttribute('data-price'),size:sz.getAttribute('data-size')||''}:null;
  }
  function writePrice(price,size){
    if(!pdpPrice)return;
    pdpPrice.hidden=false;
    pdpPrice.classList.remove('pending');
    pdpPrice.innerHTML=price+'<span class="g">'+size+'</span>';
  }
  function noteRows(item){
    return item.notes||NOTE_FALLBACK[currentCat]||NOTE_FALLBACK.bars;
  }
  function renderNotes(item){
    if(!pdpNotes)return;
    pdpNotes.innerHTML=noteRows(item).map(function(n){return '<span><b>'+n[0]+'</b>'+n[1]+'</span>';}).join('');
  }
  function renderProof(item,state){
    if(!pdpProof)return;
    var pack=activePack();
    var size=(pack&&pack.size)||item.size||'';
    var rows=state.priced?['Shop page pricing',size,'Naturally sweet',state.label||'Available now']:['Enquire for details'];
    pdpProof.innerHTML=rows.map(function(row){return '<span>'+row+'</span>';}).join('');
    pdpProof.classList.toggle('pending',!state.priced);
  }
  function setPdp(item){
    var state=PRICE_STATE[currentCat]||{priced:false,label:'Enquire for details'};
    if(pdpEyebrow)pdpEyebrow.textContent=CAT_LABEL[currentCat]||'Selected flavour';
    if(pdpName)pdpName.innerHTML=amp(item.n);
    if(pdpDesc)pdpDesc.textContent=item.d;
    renderProof(item,state);
    renderNotes(item);
    if(state.priced){
      var pack=activePack();
      if((pack&&pack.price)||item.price){
        writePrice((pack&&pack.price)||item.price,(pack&&pack.size)||item.size);
      }else if(pdpPrice){
        pdpPrice.hidden=true;
        pdpPrice.textContent='';
      }
    }else if(pdpPrice){
      pdpPrice.hidden=true;
      pdpPrice.textContent='';
    }
    if(pdpFlag){
      pdpFlag.hidden=false;
      pdpFlag.textContent=state.label;
      pdpFlag.classList.toggle('pending',!state.priced);
    }
    if(pdpAdd){
      pdpAdd.hidden=false;
      pdpAdd.disabled=false;
      pdpAdd.textContent=state.priced?'Shop Now':'Enquire';
      pdpAdd.classList.toggle('notify',!state.priced);
    }
  }
  function setPending(cat){
    var label=CAT_FORMAT[cat]||'Featured format';
    var state=PRICE_STATE[cat]||{priced:false,label:'Enquire for details'};
    if(pdpEyebrow)pdpEyebrow.textContent=label;
    if(pdpName)pdpName.textContent=label;
    if(pdpDesc)pdpDesc.textContent='View this range or enquire with Maple Moon.';
    if(pdpProof){pdpProof.classList.add('pending');pdpProof.innerHTML='<span>Enquire for details</span>';}
    if(pdpNotes){pdpNotes.innerHTML=(NOTE_FALLBACK[cat]||NOTE_FALLBACK.bars).map(function(n){return '<span><b>'+n[0]+'</b>'+n[1]+'</span>';}).join('');}
    if(pdpPrice){pdpPrice.hidden=true;pdpPrice.textContent='';}
    if(pdpFlag){pdpFlag.hidden=false;pdpFlag.textContent=state.label;pdpFlag.classList.add('pending');}
    if(pdpAdd){pdpAdd.hidden=false;pdpAdd.disabled=false;pdpAdd.textContent='Enquire';pdpAdd.classList.add('notify');}
  }
  function renderSizes(cat){
    if(!pdpSizes)return;
    pdpSizes.innerHTML='';
    (SIZES[cat]||[]).forEach(function(s,i){
      var item=typeof s==='string'?{label:s}:s;
      var el=document.createElement('button');
      el.type='button';el.className='wf-sz'+(i===0?' on':'');el.textContent=item.label;
      el.setAttribute('aria-pressed',i===0?'true':'false');
      if(item.price)el.setAttribute('data-price',item.price);
      if(item.size)el.setAttribute('data-size',item.size);
      pdpSizes.appendChild(el);
    });
  }

  // ---- coverflow arc ----
  var els=[];      // current .cf-item nodes
  var data=[];     // current category's items
  var center=0;    // index of the centred (selected) product
  function compact(){return window.innerWidth<760;}
  // shortest signed offset of item i from centre c around a ring of N (enables infinite wrap)
  function ringOffset(i,c,N){var o=((i-c)%N+N)%N;if(o>N/2)o-=N;return o;}

  // coverflow fan geometry — read live from CSS vars so the tuner can drive it
  var CF={spread:138,outer:276,tilt:38,depth:178};
  function readCF(){
    var cs=getComputedStyle(stage);
    function n(name,def){var v=parseFloat(cs.getPropertyValue(name));return isNaN(v)?def:v;}
    CF.spread=n('--cf-spread',138); CF.outer=n('--cf-outer-spread',CF.spread*2); CF.tilt=n('--cf-tilt',38); CF.depth=n('--cf-depth',178);
  }

  // transform for an item at its ring offset (descending z keeps side edges clickable)
  function placeOf(off,N){
    var a=Math.abs(off),sign=off<0?-1:1,c=compact();
    // the single diametrically-opposite bar (even rings) parks behind centre, faded -> seamless loop, no side-sweep
    if(N>=4 && N%2===0 && a===N/2){
      return {tr:'translateX(0px) translateY('+(c?22:30)+'px) translateZ(-'+(c?560:720)+'px) rotateY(0deg) scale('+(c?.48:.52)+')',op:0,z:0,pe:'none'};
    }
    if((c&&a>1)||a>2){
      return {tr:'translateX('+(sign*(c?300:480))+'px) translateZ(-'+(c?560:720)+'px) rotateY('+(sign*48)+'deg) scale(.5)',op:0,z:0,pe:'none'};
    }
    // The outer pair is set by visible edge gaps, not a simple doubled offset.
    // This keeps the angled packs optically even and pulls the full fan together.
    var x=a===0?0:sign*(a===1?CF.spread:CF.outer)*(c?0.67:1);
    var z=0;
    // Keep the selected pack front-on while the flanking packs open outward.
    // Left turns left and right turns right, so each pack faces away from centre.
    var ry=a===0?0:sign*(a===1?30:38);
    var y=-a*(c?13:32);                        // packages rise out from the centre
    var s=a===0?1:(a===1?.8:.6);               // near pair 80%, outer pair 60%
    var op=1;
    return {tr:'translateX('+x+'px) translateY('+y+'px) translateZ('+z+'px) rotateY('+ry+'deg) scale('+s+')',op:op,z:100-a,pe:'auto'};
  }
  function layout(){
    var N=els.length;if(!N)return;
    readCF();
    for(var i=0;i<N;i++){
      var off=ringOffset(i,center,N),p=placeOf(off,N),el=els[i];
      el.style.transform=p.tr;el.style.opacity=p.op;el.style.zIndex=p.z;el.style.pointerEvents=p.pe;
      var hidden=(p.pe==='none');                          // back-parked / culled bars: keep them out of the tab order + SR tree
      el.hidden=hidden;
      el.tabIndex=hidden?-1:0;
      if(hidden)el.setAttribute('aria-hidden','true');else el.removeAttribute('aria-hidden');
      if(off===0)el.classList.add('center');else el.classList.remove('center');
      if(off===0)el.setAttribute('aria-current','true');else el.removeAttribute('aria-current');
    }
  }
  function selectIndex(i){
    var N=data.length;if(!N)return;
    center=((i%N)+N)%N;                      // wrap both ends -> infinite
    layout();if(data[center])setPdp(data[center]);
  }
  function renderPending(cat){
    stage.innerHTML='<div class="wf-range-pending"><p>Enquire about this range.</p></div>';
    els=[];center=0;setPending(cat);
  }
  function repeatToFillRail(items){
    var repeated=items.slice();
    if(!repeated.length)return repeated;
    for(var i=repeated.length;i<5;i++)repeated.push(items[i%items.length]);
    return repeated;
  }
  function render(cat){
    currentCat=cat;
    updateTabs(cat);
    var sourceData=CAT[cat]||[];
    data=repeatToFillRail(sourceData);stage.innerHTML='';els=[];stage.setAttribute('data-cat',cat);renderSizes(cat);
    if(rangeCopy)rangeCopy.textContent=RANGE_COPY[cat]||'';
    if(!data.length){renderPending(cat);updateArrows();return;}
    var initial=0;
    for(var si=0;si<sourceData.length;si++){if(sourceData[si].sel){initial=si;break;}}
    data.forEach(function(item,i){
      var el=document.createElement('button');
      el.type='button';el.className='cf-item';el.setAttribute('aria-label',item.n);
      var bp=document.createElement('div');bp.className='cf-bp';
      var img=document.createElement('img');img.src=PS+item.img+'.webp';img.alt=item.n;img.loading=i<5?'eager':'lazy';img.draggable=false;
      bp.appendChild(img);el.appendChild(bp);
      el.addEventListener('click',function(){if(i!==center)selectIndex(i);});
      stage.appendChild(el);els.push(el);
    });
    center=initial;layout();if(data[center])setPdp(data[center]);updateArrows();
  }

  function selectCategory(cat){if(cat&&cat!==currentCat)render(cat);}
  function rotateCategory(step){
    var next=CAT_ORDER[(catIndex(currentCat)+step+CAT_ORDER.length)%CAT_ORDER.length];
    render(next);
  }
  tabs.addEventListener('click',function(e){
    var t=e.target.closest('.wf-tab');if(!t)return;
    selectCategory(t.getAttribute('data-cat'));
  });
  // size pills are re-rendered per category; delegate the toggle to the container
  if(pdpSizes)pdpSizes.addEventListener('click',function(e){
    var sz=e.target.closest('.wf-sz');if(!sz)return;
    pdpSizes.querySelectorAll('.wf-sz').forEach(function(s){s.classList.remove('on');s.setAttribute('aria-pressed','false');});
    sz.classList.add('on');
    sz.setAttribute('aria-pressed','true');
    var state=PRICE_STATE[currentCat]||{priced:false};
    if(state.priced&&sz.getAttribute('data-price'))writePrice(sz.getAttribute('data-price'),sz.getAttribute('data-size')||'');
    if(data[center])renderProof(data[center],state);
  });
  if(pdpAdd)pdpAdd.addEventListener('click',function(){
    var state=PRICE_STATE[currentCat]||{priced:false};
    var item=data[center];
    if(state.priced){
      window.location.href=(item&&item.url)||shopTarget(currentCat);
      return;
    }
    window.location.href='mailto:info@maplemoon.com.au?subject=Enquiry%20about%20'+encodeURIComponent(item?item.n:CAT_FORMAT[currentCat]);
  });

  var line=document.querySelector('.wf-line');
  var l=line.querySelector('.arw.l'),r=line.querySelector('.arw.r');
  function updateArrows(){
    var hide=data.length<2;
    if(l)l.hidden=hide;
    if(r)r.hidden=hide;
  }
  if(l)l.addEventListener('click',function(){selectIndex(center-1);});
  if(r)r.addEventListener('click',function(){selectIndex(center+1);});
  if(catPrev)catPrev.addEventListener('click',function(){rotateCategory(-1);});
  if(catNext)catNext.addEventListener('click',function(){rotateCategory(1);});

  // keyboard arrows: act only when focus is within the selector, or when nothing else holds focus and the arc is in view
  function inSelector(n){return n&&(stage.contains(n)||tabs.contains(n)||(line&&line.contains(n)));}
  document.addEventListener('keydown',function(e){
    if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight')return;
    var a=document.activeElement,idle=(!a||a===document.body);
    if(tabs.contains(a)){
      e.preventDefault();
      rotateCategory(e.key==='ArrowRight'?1:-1);
      var active=tabs.querySelector('.wf-tab.on');
      if(active)active.focus({preventScroll:true});
      return;
    }
    if(!idle&&!inSelector(a))return;                                   // another control is focused -> leave its arrows alone
    if(idle){var box=stage.getBoundingClientRect();if(box.bottom<40||box.top>window.innerHeight-40)return;}
    e.preventDefault();selectIndex(center+(e.key==='ArrowRight'?1:-1));
  });

  // touch swipe to step the arc
  var tx=0,ty=0,sw=false;
  stage.addEventListener('touchstart',function(e){var t=e.changedTouches[0];tx=t.clientX;ty=t.clientY;sw=true;},{passive:true});
  stage.addEventListener('touchend',function(e){
    if(!sw)return;sw=false;var t=e.changedTouches[0],dx=t.clientX-tx,dy=t.clientY-ty;
    if(Math.abs(dx)>40&&Math.abs(dx)>Math.abs(dy))selectIndex(center+(dx<0?1:-1));
  },{passive:true});
  if(catDock){
    catDock.addEventListener('touchstart',function(e){var t=e.changedTouches[0];tx=t.clientX;ty=t.clientY;sw=true;},{passive:true});
    catDock.addEventListener('touchend',function(e){
      if(!sw)return;sw=false;var t=e.changedTouches[0],dx=t.clientX-tx,dy=t.clientY-ty;
      if(Math.abs(dx)>40&&Math.abs(dx)>Math.abs(dy))rotateCategory(dx<0?1:-1);
    },{passive:true});
  }

  var rt;window.addEventListener('resize',function(){clearTimeout(rt);rt=setTimeout(layout,120);});
  // re-render the fan when CSS vars change on .wf (e.g. the tuning playground adjusting --cf-* live)
  try{ new MutationObserver(function(){clearTimeout(rt);rt=setTimeout(layout,60);}).observe(document.querySelector('.wf'),{attributes:true,attributeFilter:['style']}); }catch(e){}

  render('bars');
})();
(function(){
  var slides=document.querySelectorAll('.qslide'),dots=document.querySelectorAll('.qdots span');if(!slides.length)return;
  var i=0;function go(n){i=((n%slides.length)+slides.length)%slides.length;
    slides.forEach(function(sl,j){sl.classList.toggle('on',j===i);});
    dots.forEach(function(d,j){d.classList.toggle('on',j===i);});}
  var l=document.querySelector('.qarw.l'),r=document.querySelector('.qarw.r');
  var t=setInterval(function(){go(i+1);},6500);
  function hold(){clearInterval(t);t=setInterval(function(){go(i+1);},6500);}
  if(l)l.addEventListener('click',function(){go(i-1);hold();});
  if(r)r.addEventListener('click',function(){go(i+1);hold();});
  var qs=document.querySelector('.qslider');
  if(qs){qs.addEventListener('mouseenter',function(){clearInterval(t);});qs.addEventListener('mouseleave',hold);}
})();

