  var s1=q.get('s1')||'ocean';
  if(S1[s1]){
    var c=S1[s1],bg=document.querySelector('.wf-phero .bg');
    if(bg){bg.style.background="url('"+c.img+"') "+c.pos+" / cover no-repeat";bg.style.filter='none';bg.style.backgroundBlendMode='normal';}
